(function () {
    // CSS Classes
    var patternClass = 'osui-accordion-item';
    var patternTitleClass = 'osui-accordion-item__title';
    var patternIconClass = 'osui-accordion-item__icon';
    var patternContentClass = 'osui-accordion-item__content';
    var patternOpen = 'osui-accordion-item--is-open';
    var isDisabledClass = 'osui-accordion-item--is-disabled';

    // Icon Classes
    var caretClass = 'osui-accordion-item__icon--caret';
    var plusClass = 'osui-accordion-item__icon--plus-minus';
    var customClass = 'osui-accordion-item__icon--custom';
    var hiddenClass = 'osui-accordion-item__icon--hidden';

    //Icon position
    var left = 'osui-accordion-item__title--is-left';

    // HTML Elements
    var patternWrapper = this.querySelector('.' + patternClass);
    var patternTitle = this.querySelector('.' + patternTitleClass);
    var patternIcon = this.querySelector('.' + patternIconClass);
    var patternIconCustom = this.querySelector('.ph.' + patternIconClass);
    var patternContent = this.querySelector('.' + patternContentClass);


    // Parameters values
    var extendedClass = '

';

    if(isDisabled === false) {
        isDisabledClass = '';
    }

    /* Apply styles of extendedClass */
    if (typeof patternWrapper !== 'undefined' && patternWrapper) {
        patternWrapper.setAttribute('class', patternClass + ' ' + isDisabledClass + ' ' + extendedClass);

        if (iconPosition === 'left') {
            patternTitle.classList.add(left);
        } else {
            patternTitle.classList.remove(left);
        }
    }

    if(patternIcon) {
        switch(iconType) {
            case 'PlusMinus':
                patternIcon.classList.remove(caretClass);
                patternIcon.classList.add(plusClass);
                patternIcon.classList.remove(hiddenClass);
                patternIconCustom.classList.add(hiddenClass);
                patternIconCustom.classList.remove(customClass);
                break;
            case 'Custom':
                patternIconCustom.classList.remove(hiddenClass);
                patternIcon.classList.add(hiddenClass);
                patternIcon.classList.remove(caretClass);
                patternIcon.classList.remove(plusClass);
                patternIconCustom.classList.add(customClass);
                break;
            case 'Caret':
            default:
                patternIcon.classList.add(caretClass);
                patternIcon.classList.remove(plusClass);
                patternIcon.classList.remove(hiddenClass);
                patternIconCustom.classList.add(hiddenClass);
                patternIconCustom.classList.remove(customClass);
                break;
        }
    }

    if(patternContent) {
        patternWrapper.classList.add(patternOpen);
    } else {
        patternWrapper.classList.remove(patternOpen);
    }


}.bind(this)())

