Variables.ReferenceSerializableInputPara.Description:
Set the height of the map in pixels (""300px""), percentage (""100%"") or viewport height (""100vh""). If the value is empty, the map fits to the parent height.

If using percentages, make sure the map has a parent with a fixed height value, otherwise its height will be 0 (zero).

The parameter value is applied to a CSS variable, used in the OutSystems UI Theme. This variable can be overriden to manipulate the map’s height in your CSS theme. 

As an example:

.map-container {
    height: 500px;
    width: 100%;
}

Text.Value:
(function () {   
    const mapcontainer = this.querySelector('.map-container');
    const maplicense = this.querySelector('.license-message');
    const messageheight = this.querySelector('.map-preview-height');
    const messagelocation = this.querySelector('.map-preview-location');

    let height = '

';

    if(typeof mapcontainer !== 'undefined' && mapcontainer){
        if (height === '') {
                messageheight.innerText = '🛈 In runtime the map will have the height of the parent';
                height = '300px';
        } else {
            if(height === '100vh') {
                messageheight.innerText = '🛈 Runtime height will be 100vh';
                height = '300px';
            } else {
                if (isNaN(Number(height)) === false) {
                    height = height + 'px';
                }
                messageheight.innerText = '';
            }
        }
        mapcontainer.style.setProperty('--map-height', height);
    }

    if(typeof maplicense !== 'undefined' && maplicense){
        if(apiKey !== '') {
            maplicense.style.setProperty('display', 'none');

        } else {
            maplicense.style.setProperty('display', 'block');
        }
    }

    if(center !== '') {
        if(center === ',' || center === ' , ' || center === ' ,' || center === ', ') {
            center = 'latitude, longitude';
        }
        messagelocation.innerText = '📍 ' + center;
    } else {
        messagelocation.innerText = '';
    }

}.bind(this)());

